import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Gemini 高危运镜词与稳定平替","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-camera-failsafe.md","filePath":"tools/gemini-camera-failsafe.md","lastUpdated":1786871523000}'),r={name:"tools/gemini-camera-failsafe.md"};function i(l,e,c,n,s,m){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="gemini-高危运镜词与稳定平替" tabindex="-1">Gemini 高危运镜词与稳定平替 <a class="header-anchor" href="#gemini-高危运镜词与稳定平替" aria-label="Permalink to &quot;Gemini 高危运镜词与稳定平替&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经官方文档逐一核实；不同视频模型（Veo、Runway、Kling 等）对运镜词的支持程度不同，请以各自官方文档为准。</li></ul></div><blockquote><p>提问：哪些运镜词最容易翻车（比如 360° 环绕会扭曲物体），有没有更稳的同义替换？</p></blockquote><h2 id="高危运镜词与平替对照" tabindex="-1">高危运镜词与平替对照 <a class="header-anchor" href="#高危运镜词与平替对照" aria-label="Permalink to &quot;高危运镜词与平替对照&quot;">​</a></h2><p>在当前视频生成模型（Veo、Runway、Kling 等）中，包含「极端角度跨度」「复杂光学物理」或「超高运动速度」的运镜词最容易导致物体形变与像素溶解。以下是 5 大高危运镜词、崩溃原因及工业级稳定替代方案：</p><table tabindex="0"><thead><tr><th>高危运镜词（易翻车）</th><th>常见崩溃表现</th><th>稳定平替词（Prompt Safe Alternatives）</th></tr></thead><tbody><tr><td><code>360-degree orbit / full spin</code><br>（360° 全景环绕）</td><td>转到盲区时模型「脑补」背面结构，导致物体扭曲、多长肢体或 Logo 变形融化</td><td><code>180-degree orbital arc shot</code>／<code>subtle 90-degree semicircular pan</code><br>（限制在 90°~180° 半弧范围内，始终保留部分原始视角锚点）</td></tr><tr><td><code>Dolly zoom / Vertigo effect</code><br>（希区柯克变焦 / 滑动变焦）</td><td>FOV 视场角变化与相机位移混合运算失败，背景与边缘产生液化拉伸、画质劣化</td><td><code>Smooth dolly-in with rack focus</code>／<code>Push-in with shallow depth of field</code><br>（将光学畸变拆解为「机位推进 + 焦点虚实切换」）</td></tr><tr><td><code>Crash zoom / Snap zoom</code><br>（瞬间急推暴拉）</td><td>极短时间内光学流（Optical Flow）速度过快，导致画面严重撕裂、产生噪波伪影</td><td><code>Rapid linear push-in along z-axis</code>／<code>High-speed macro focus pull</code><br>（指定单轴高速推进，而非瞬间焦距突变）</td></tr><tr><td><code>Fly-through / Passing through</code><br>（穿过障碍物 / 穿模运镜）</td><td>模型缺乏刚体碰撞体积概念，镜头穿过物体时会产生「穿模融化」或超现实粘连</td><td><code>Foreground wipe / Parallax reveal</code>／<code>Sliding closely past [Object] into background</code><br>（改为前景遮挡后「划出揭示」，规避物理穿透）</td></tr><tr><td><code>Shaky cam / FPV drone chaos</code><br>（剧烈手持晃动 / 失控穿越机）</td><td>随机加速度过大破坏帧间连续性（Temporal Consistency），导致主体结构瓦解</td><td><code>Organic handheld micro-movement</code>／<code>Controlled steadycam glide</code><br>（用「呼吸感微晃」或「斯坦尼康平滑跟随」控制晃动幅度）</td></tr></tbody></table><h2 id="运镜提示词稳定度三原则" tabindex="-1">运镜提示词稳定度三原则 <a class="header-anchor" href="#运镜提示词稳定度三原则" aria-label="Permalink to &quot;运镜提示词稳定度三原则&quot;">​</a></h2><p><strong>1. 限制单镜头角度 ≤ 180°</strong>：在单次 3~5 秒生成中，绝不要让相机跨越超过半圆的范围。需要展示全貌时，拆分为「正面微推」与「背面特写」两个分镜。</p><p><strong>2. 锁定单一运动轴（Single Axis Rule）</strong>：避免同时指令「边旋转边上升边推近」（Spiral Crane In）。每次只给 1 个主运动轴（如纯 Z 轴推进 <code>dolly-in</code>，或纯 X 轴横移 <code>truck left</code>）。</p><p><strong>3. 用视差（Parallax）替代大范围位移</strong>：想表现立体空间感时，加入 <code>shallow depth of field</code>、<code>clear cinematic parallax between foreground and background</code>，让前后景相对位移代替大幅度机位乱晃。</p><hr><p>关联：本文是 <a href="/tools/gemini-camera-movement">机位与运镜</a> 的避坑配套——那篇给出俯拍 / 环形 / dolly-in 的正确写法，这篇补充哪些运镜词要避开、以及对应的安全平替。</p>',12)])])}const g=o(r,[["render",i]]);export{p as __pageData,g as default};
